export const samples = [
{id:'number',name:'数轴与绝对值',chapter:'有理数',topic:'数轴、绝对值、两点距离',question:'数轴上 A 点表示 −3，B 点表示 2。求 A、B 两点间的距离，并解释为什么不能直接把两个数相加。',attempt:'我把 −3 和 2 相加，得到 −1，但距离不应该是负数。',known:'A 在原点左侧 3 个单位，B 在原点右侧 2 个单位。',ask:'要求两点的距离，也就是从 A 走到 B 一共走了多少个单位长度。',principle:'距离是长度，不能为负；跨过原点时，可以把两段距离相加。',diagram:{type:'number',min:-5,max:4,a:-3,b:2},hints:['先在数轴上标出 A、原点 O 和 B。A 到 O 有多远？O 到 B 有多远？','A 和 B 位于原点两侧，AB = AO + OB。相加的是两段长度，不是带方向的坐标。'],steps:['画图：A(−3) 在左，O(0) 居中，B(2) 在右。','找数量关系：AB = AO + OB。','列式：AO = |−3| = 3，OB = |2| = 2，所以 AB = 3 + 2 = 5。','检验：从 −3 向右走 5 格正好到 2，距离为 5 个单位长度。'],answer:'5 个单位长度',key:'坐标有正负，距离没有负数；先看点的位置，再找长度关系。',error:'把坐标和距离混淆；直接把两个带符号的坐标相加。',method:['标出原点、正方向和单位长度。','按坐标标点，检查左右位置。','将需要的距离拆成已知线段。','依据位置关系列式计算。','沿数轴数格并核对长度非负。'],variant:'A 点表示 −4，B 点表示 3。两点距离是多少？',variantAnswer:7,variantExplain:'跨过原点：4 + 3 = 7。',why:'−3 表示位置，不表示一段负的长度。A 到原点是 3，原点到 B 是 2，所以两段长度相加得到 5。',alternate:'也可以看坐标的差：右端坐标减左端坐标，2 − (−3) = 5。先用画图理解，再记住这个关系。'},
{id:'segment',name:'线段与几何关系',chapter:'几何图形初步',topic:'线段和差、中点',question:'点 C 在线段 AB 上，AB = 12 cm，AC = 5 cm。点 D 是 CB 的中点。求 CD 的长。',attempt:'我不确定中点应当把哪一段平分。',known:'C 在线段 AB 上，AB = 12 cm，AC = 5 cm；D 是 CB 的中点。',ask:'要求 CD。先求 CB，再利用中点把 CB 平分。',principle:'线段的和差关系与中点定义：CB = AB − AC；CD = CB ÷ 2。',diagram:{type:'segment',ab:12,ac:5},hints:['请先按 A、C、D、B 的顺序画图。AB 是整段，AC 已知，剩下 CB 是多少？','D 是 CB 的中点，所以平分的是 CB，不能把 AB 直接除以 2。'],steps:['画图：C 在线段 AB 内，D 在 C 与 B 之间。','找关系：CB = AB − AC；由中点定义，CD = DB = CB ÷ 2。','列式：CB = 12 − 5 = 7 (cm)，CD = 7 ÷ 2 = 3.5 (cm)。','检验：AC + CD + DB = 5 + 3.5 + 3.5 = 12 (cm)，与 AB 一致。'],answer:'3.5 cm',key:'“谁的中点”，就把谁平分；先认清整段与部分。',error:'看见“中点”就把整条 AB 除以 2，忽略了 D 是 CB 的中点。',method:['根据条件确定点的先后顺序。','标注已知整段和部分长度。','用线段和差求目标所在的线段。','依照中点定义平分指定线段。','将各部分相加，检验是否等于整段。'],variant:'C 在线段 AB 上，AB = 18 cm，AC = 8 cm，D 是 CB 的中点。CD 是多少厘米？',variantAnswer:5,variantExplain:'CB = 18 − 8 = 10，CD = 10 ÷ 2 = 5 cm。',why:'中点有明确的对象。D 是 CB 的中点，因此 CD 和 DB 相等；题目没有说 C 或 D 是 AB 的中点。',alternate:'可设 CD = x cm，则 DB = x cm。由 AC + CD + DB = AB，得 5 + 2x = 12，解得 x = 3.5。'},
{id:'work',name:'工程问题',chapter:'一元一次方程的应用',topic:'工作总量、效率、合作时间',question:'一项工程，甲单独做需要 6 天完成，乙单独做需要 12 天完成。两人合作，每天工作效率不变，需要几天完成？',attempt:'我想把 6 天和 12 天直接相加，但不知道这样表示什么。',known:'甲 6 天完成，乙 12 天完成；合作时各自效率不变。',ask:'要求两人合作完成整项工程所需的天数。',principle:'工作量 = 工作效率 × 时间；甲完成量 + 乙完成量 = 总工作量。',diagram:{type:'work',a:6,b:12},hints:['把整项工程看作“1”。甲每天完成六分之一，乙每天完成十二分之一。','设合作 x 天，甲做 x/6，乙做 x/12。两人的工作量相加应等于 1。'],steps:['画图：将整项工程平均分成 12 份，甲每天做 2 份，乙每天做 1 份。','找关系：甲工作量 + 乙工作量 = 整项工程。','设合作 x 天，列方程 x/6 + x/12 = 1；两边同乘 12，得 2x + x = 12，解得 x = 4。','检验：甲做 4/6，乙做 4/12，共 1；4 天少于 6 天和 12 天，符合合作应更快的直觉。'],answer:'4 天',key:'总量看作 1，效率用“每天完成几分之几”；合作相加的是效率。',error:'把单独完成的天数直接相加；混淆时间、效率和工作量。',method:['定总量：把整项工程看作 1。','求效率：分别写出每天完成总量的几分之几。','设未知：设所求时间为 x 天，标明单位。','列方程：各自效率 × 各自时间的和 = 1。','解并验：代回总量关系，检查合作时间是否合理。'],variant:'甲单独做需 8 天，乙单独做需 24 天，合作完成需要几天？',variantAnswer:6,variantExplain:'x/8 + x/24 = 1，乘 24 得 3x + x = 24，所以 x = 6 天。',why:'天数表示完成整项工程要用多久，不能直接表示每天做多少。合作时同一天里两人都在工作，所以应该把同一天完成的工作量相加。',alternate:'先算合作效率：1/6 + 1/12 = 1/4，即一天做总量的四分之一。因此总时间 = 1 ÷ (1/4) = 4 天。'},
{id:'kit',name:'配套问题',chapter:'一元一次方程的应用',topic:'总人数、生产效率、配套数量',question:'某车间有 20 名工人。每名工人每天可加工 4 个螺栓或 6 个螺母，每个螺栓配 2 个螺母。怎样分配工人，才能使每天加工的螺栓和螺母恰好配套？',attempt:'我把两种产量设成相等，但题目说每个螺栓需要 2 个螺母。',known:'总人数 20；螺栓每人每天 4 个；螺母每人每天 6 个；1 个螺栓配 2 个螺母。',ask:'要求两组工人人数，使螺母总数恰好是螺栓总数的 2 倍。',principle:'总人数关系：两组人数之和 = 20。配套关系：螺母产量 = 2 × 螺栓产量。',diagram:{type:'kit',total:20,bolts:4,nuts:6,ratio:2},hints:['先画出一套：1 个螺栓对应 2 个螺母。两类产量能直接相等吗？','设做螺栓的有 x 人，那么做螺母的有 20 − x 人。每天螺栓有 4x 个，螺母有 6(20 − x) 个。'],steps:['画图：每套是“1 个螺栓 + 2 个螺母”，因此螺母产量应是螺栓的 2 倍。','找关系：螺母产量 = 2 × 螺栓产量；两组工人人数共 20。','设做螺栓的 x 人，做螺母的 20 − x 人；列 6(20 − x) = 2 × 4x。展开得 120 − 6x = 8x，解得 x = 60/7。','检验：60/7 不是整数，另一组为 80/7，也不是整数。按“每位工人全天只加工一种零件”的通常含义，这个题设没有整数人数解。应先核对总人数或其他条件，不能四舍五入后宣称恰好配套。'],answer:'该条件下无整数人数解，需核对题设或允许分时加工。',key:'先画“一套”，把配套比例翻译成产量关系；人数必须检验为非负整数。',error:'把两种产量直接设相等；把分数人数四舍五入，仍称恰好配套。',method:['画一套：写清每套各类零件的数量。','设人数：用总人数表示另一组人数。','写产量：人数 × 每人每天产量。','列比例：按一套的需求比建立产量关系。','解并验：检查人数为非负整数，再核对总人数与配套比例。'],variant:'把总人数改为 21，其余条件不变。安排多少人加工螺栓，才能恰好配套？',variantAnswer:9,variantExplain:'6(21 − x) = 8x，得 x = 9。螺栓 36 个，螺母 72 个，恰好 1∶2 配套。',why:'配套要求螺母是螺栓的 2 倍，不是相等。原题解出分数人数，说明这些条件和整人分工不能同时满足，不能为了给答案而忽略实际意义。',alternate:'每 3 名螺栓工人每天做 12 个螺栓，需要 24 个螺母，对应 4 名螺母工人。两组人数比为 3∶4，总人数应是 7 的倍数。20 不是 7 的倍数。'}
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function graph(d){
 const base=(body,title)=>'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 200" role="img" aria-label="'+esc(title)+'"><title>'+esc(title)+'</title><rect width="560" height="200" fill="#fcfdf9"/><g font-family="sans-serif" font-size="14" fill="#395b43">'+body+'</g></svg>';
 if(d.type==='number'){const x=n=>60+(n-d.min)*440/(d.max-d.min);let lines='';for(let n=d.min;n<=d.max;n++)lines+='<path d="M'+x(n)+' 100 v8" stroke="#7a8f71"/><text x="'+x(n)+'" y="131" text-anchor="middle">'+n+'</text>';return base('<path d="M45 100H520l-10 -6m10 6l-10 6" stroke="#7a8f71" fill="none"/>'+lines+'<path d="M'+x(d.a)+' 75v-20H'+x(d.b)+'v20" stroke="#c4a269" fill="none" stroke-width="2"/><text x="'+(x(d.a)+x(d.b))/2+'" y="40" text-anchor="middle">AB 距离 = ? 个单位长度</text>'+[[d.a,'A'],[0,'O'],[d.b,'B']].map(([n,t])=>'<circle cx="'+x(n)+'" cy="100" r="5" fill="#3f7651"/><text x="'+x(n)+'" y="85" text-anchor="middle">'+t+'</text>').join('')+'<text x="280" y="175" text-anchor="middle">先看位置，再找距离</text>','数轴上 A 表示'+d.a+'，B 表示'+d.b+'；请观察两点间的距离');}
 if(d.type==='segment'){const ac=60+440*d.ac/d.ab,mid=(ac+500)/2;return base('<path d="M60 95H500" stroke="#5e8059" stroke-width="3"/>'+[[60,'A'],[ac,'C'],[mid,'D'],[500,'B']].map(([x,n])=>'<path d="M'+x+' 87v16" stroke="#5e8059"/><text x="'+x+'" y="75" text-anchor="middle">'+n+'</text>').join('')+'<text x="'+(60+ac)/2+'" y="127" text-anchor="middle">'+d.ac+' cm</text><text x="'+(ac+mid)/2+'" y="127" text-anchor="middle">?</text><text x="'+(mid+500)/2+'" y="127" text-anchor="middle">?</text><path d="M60 145v12H500v-12" stroke="#bca16e" fill="none"/><text x="280" y="180" text-anchor="middle">AB = '+d.ab+' cm；CD = DB</text>','按比例绘制的 A C D B 线段，中点 D 平分 CB');}
 if(d.type==='work'){let squares='';for(let i=0;i<12;i++)squares+='<rect x="'+(58+i*37)+'" y="50" width="34" height="34" rx="3" fill="'+(i<2?'#7c9e6a':i===2?'#d9ba7c':'#e7edde')+'" stroke="#d0dbc7"/>';return base('<text x="58" y="28">整项工程看作 1，平均分成 12 份</text>'+squares+'<rect x="58" y="115" width="16" height="16" fill="#7c9e6a"/><text x="86" y="128">甲每天：2 份 = 1/6</text><rect x="310" y="115" width="16" height="16" fill="#d9ba7c"/><text x="338" y="128">乙每天：1 份 = 1/12</text><text x="280" y="174" text-anchor="middle">合作每天共几份？先找效率，再求时间</text>','工程总量十二等份，甲每天二份，乙每天一份');}
 if(d.type==='kit')return base('<rect x="72" y="57" width="14" height="65" rx="3" fill="#8ea083"/><rect x="62" y="50" width="34" height="15" rx="3" fill="#5e7d52"/><text x="80" y="150" text-anchor="middle">1 个螺栓</text><text x="170" y="100" font-size="25">配</text>'+[260,340].map(x=>'<polygon points="'+x+',63 '+(x+25)+',78 '+(x+25)+',107 '+x+',122 '+(x-25)+',107 '+(x-25)+',78" fill="#d8ba7b"/><circle cx="'+x+'" cy="92" r="12" fill="#fcfdf9"/>').join('')+'<text x="300" y="150" text-anchor="middle">2 个螺母</text><text x="440" y="77" text-anchor="middle">产量关系</text><text x="440" y="106" text-anchor="middle">螺母 = 2 × 螺栓</text><text x="280" y="185" text-anchor="middle">示意图表示每套比例，不表示工人人数</text>','一套包含一个螺栓和两个螺母，螺母产量是螺栓的两倍');
 return '';
}
